def kthSquareFree(k):
    hi = 2 * k + 10
    limit = int(hi ** 0.5) + 2
    mu = [1] * (limit + 1)
    is_comp = [False] * (limit + 1)
    primes = []
    for i in range(2, limit + 1):
        if not is_comp[i]:
            primes.append(i)
            mu[i] = -1
        for p in primes:
            if i * p > limit:
                break
            is_comp[i * p] = True
            if i % p == 0:
                mu[i * p] = 0
                break
            mu[i * p] = -mu[i]
    terms = [(d * d, mu[d]) for d in range(1, limit + 1) if mu[d] != 0]

    def count(x):
        total = 0
        for sq, m in terms:
            if sq > x:
                break
            total += m * (x // sq)
        return total

    lo = 1
    while lo < hi:
        mid = (lo + hi) // 2
        if count(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo
